#!/usr/bin/env ruby
require_relative 'lib/era_zero_validation'
require_relative 'lib/era_zero_compound_conventions'
V=EraZeroValidation
d=V.load_yaml('lexicon/compound_dictionary.yaml');reviews=V.load_yaml('reviews/gate4b_high_frequency_compounds_scored_candidates.yaml')
before=V.fingerprint(d['entries']);prior=d['entries'].map{|e|e['compound_id']}
fetch=lambda{|key|d['entries'].find{|e|e.dig('conventional_meaning','sense_key')==key}||raise('Missing spatial dependency '+key)}
exterior=fetch.call('physical_region_exterior');interior=fetch.call('physical_region_interior')
definition="An ongoing physical entry process: the same material participant is undergoing inward displacement as part of a boundary-crossing traversal from the exterior of the same contextual physical region toward an interior culmination. The exterior relation supplies the pre-crossing phase of this same process, not an assertion that the participant is still wholly outside now. The relevant extent, region and shared spatial frame remain fixed by the same contextual criterion. The target condition uses the established physical-region interior meaning: the relevant extent lies wholly inside without meeting the boundary. This is a culmination criterion, not an asserted interior state. Immediate approach integral to the crossing and partial boundary traversal are included; merely traveling toward a remote region, moving parallel to its boundary or waiting outside is insufficient. The process may be interrupted, reversed or abandoned before culmination. Neither boundary contact at this instant nor completed entry, current interior location, prescribed manner, intention, permission, ownership or later continued presence is asserted. Stationary enclosure or a changed region interpretation without mover displacement is excluded."
excludes=['Completed entry or current interior location inferred from an ongoing process','Remote approach, parallel movement or waiting without the entry traversal being underway','Different participants, regions, frames or extent criteria across the process','Stationary enclosure or figurative entry','Runtime state used as a substitute for completion or grammatical aspect']
actor_paths=[['q-0-before','s-bearer'],['s-actor']];region_paths=[['q-0-before','s-region'],['s-region']]
payload={'architecture_version'=>'1.0','semantic_head'=>'h','nodes'=>[{'node_id'=>'q-0-before','kind'=>'compound_ref','compound_id'=>exterior['compound_id'],'definition_version'=>'1.0.0'},{'node_id'=>'s-actor','kind'=>'slot','slot_name'=>'entering_participant','slot_type'=>'entity'},{'node_id'=>'s-region','kind'=>'slot','slot_name'=>'entered_region','slot_type'=>'entity'},{'node_id'=>'h','kind'=>'root','root_id'=>'MOV:121'}],'edges'=>[{'type'=>'qualifies','from'=>'q-0-before','to'=>'h'},{'type'=>'fills_role','from'=>'s-actor','to'=>'h','role'=>'actor'},{'type'=>'fills_role','from'=>'s-region','to'=>'h','role'=>'environment'}],'binding_constraints'=>[{'relation'=>'same_argument','slot_paths'=>actor_paths},{'relation'=>'same_argument','slot_paths'=>region_paths}],'lexical_constraints'=>['The nested exterior relation is the pre-crossing phase of the ongoing traversal, not a current exterior assertion. No actual interior-state component is included.','The mover is the same material bearer as in the exterior pre-phase; the region anchors the same shared frame throughout.','No nested spatial state has an independent runtime ending or speech-time assertion.'],'conventional_meaning'=>{'profile'=>'EZLEX-1','sense_key'=>'ongoing_physical_entry','sound_code'=>30,'added_definition'=>definition,'excludes'=>excludes}}
digest=V.fingerprint(payload);id="CMP:#{digest[0,24]}"
entry=payload.merge('compound_id'=>id,'content_digest'=>digest,'definition_version'=>'1.0.0','status'=>'approved','approval_date'=>'2026-11-04','display_title'=>'ongoing physical entry','english_glosses'=>['ongoing physical entry'],'invariant_definition'=>definition,'boundaries'=>{'includes'=>definition,'excludes'=>excludes.join('; ')},'collision_audit'=>'reviews/spatial_entry_foundation.md; Ongoing displacement plus an exterior pre-phase does not entail entry-directed traversal; the convention supplies that commitment without asserting the target interior state.','confidence'=>'high','approval_record'=>'migrations/ongoing_entry_2026_11_04.yaml','approval_basis'=>'Author semantic review under the user-directed translator completion goal; not independent linguistic validation.','examples'=>{'ordinary'=>'Nora is entering the archive.','technical'=>'Same-argument constraints preserve mover and region between the exterior pre-phase and ongoing displacement.','future_compound'=>'Reuse this exact event under permission, possibility and manner-specific entry.','counterexample'=>'Nora waits outside, or travels toward a distant archive; no entry traversal is underway.'},'serialization'=>{'canonical_format'=>'EZC-JSON-1','content_digest'=>digest})
old=d['entries'].find{|e|e['compound_id']==id};raise 'Existing entry changed' if old&&old!=entry;d['entries']<<entry unless old
unless reviews['reviews'].any?{|r|r['compound_id']==id}
 candidates=[['explicit_entry_convention','Preserve an exterior pre-phase and ongoing displacement, with an explicit entry-directed traversal and no interior culmination assertion.',[9,10,10,9,9,10,8,10],'winner'],['completed_event','Completed entry incorrectly entails an actual culmination.',[9,10,10,2,3,5,4,5],'rejected'],['generic_approach','Movement toward a remote region need not be entry in progress.',[5,5,6,2,3,4,3,4],'rejected']].map{|name,reason,scores,decision|{'candidate_id'=>name,'direction'=>reason,'scores'=>V::SCORE_KEYS.zip(scores).to_h,'total'=>scores.sum,'decision'=>decision}}
 candidates[0]['graph']=payload.slice('semantic_head','nodes','edges','conventional_meaning','binding_constraints')
 reviews['reviews']<<{'compound_id'=>id,'display_title'=>entry['display_title'],'current_choice_reason'=>'reviews/spatial_entry_foundation.md; author judgments, not independent validation.','candidates'=>candidates,'recommendation'=>'approve explicit_entry_convention','confidence'=>'high'}
end
EraZeroCompoundConventions.validate!(d['entries']);d['entries'].sort_by!{|e|e['compound_id']};d['metadata']['entry_count']=d['entries'].length
V.write('lexicon/compound_dictionary.yaml',YAML.dump(d));V.write('reviews/gate4b_high_frequency_compounds_scored_candidates.yaml',YAML.dump(reviews))
migration='migrations/ongoing_entry_2026_11_04.yaml';V.write(migration,YAML.dump({'authority'=>'User-directed translator-completion goal','review'=>'reviews/spatial_entry_foundation.md','before_dictionary_fingerprint'=>before,'previous_compound_ids'=>prior,'added_compound_id'=>id,'dependencies'=>[exterior['compound_id']],'target_condition_definition'=>{'compound_id'=>interior['compound_id'],'definition_version'=>'1.0.0','asserted'=>false},'new_convention_code'=>30,'existing_meanings_changed'=>false})) unless File.exist?(File.join(V::ROOT,migration))
V.write('pages/ongoing_entry.mjs',"export const ONGOING_ENTRY = #{JSON.generate({requiredInterpretation:'physical_entry',pattern:'is entering',negativePattern:'is not entering',predicate:id,key:'ongoing_physical_entry',wording:'is entering',role:'actor',targetRole:'environment',compoundSlots:{actor:actor_paths,environment:region_paths},semanticNote:definition})};\n")
puts id
